int
print_ipv6_routing_hdr(netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
    const struct ip6_rthdr *rthdr;
    int len, i;

    rthdr = (const struct ip6_rthdr *)bp;

    ND_TCHECK(*rthdr);
    if (ndo->ndo_vflag < 1)
        ND_TCHECK2(rthdr->ip6r_len, sizeof(rthdr->ip6r_len));
    else
        ND_TCHECK2(rthdr->ip6r_len, rthdr->ip6r_len + 1);

    if (ndo->ndo_vflag < 1) {
        ND_PRINT("%s, IPv6 routing header (type %d) length %d, %d segments left",
            rthdr->ip6r_len,
            rthdr->ip6r_type,
            rthdr->ip6r_len + 1);
    } else {
        ND_PRINT("IPv6 routing header:\n  type: %d\n  length: %d\n  segments left: %d",
            rthdr->ip6r_type,
            rthdr->ip6r_len,
            rthdr->ip6r_len + 1);
    }

    switch (rthdr->ip6r_type) {
    case 0: /* Type 0 (IPv6 spec) */
        for (i = 0; i < (rthdr->ip6r_len + 1); i++) {
            ND_PRINT("  Segment %d: %s", i, ip6addr_string(ndo, &rthdr->ip6r_seg[i]));
        }
        len = sizeof(struct ip6_rthdr) + sizeof(struct in6_addr) * (rthdr->ip6r_len + 1);
        break;
    default:
        ND_PRINT(" (unknown routing type)");
        len = sizeof(struct ip6_rthdr);
        break;
    }

    return len;
}

int
print_ipv6_routing_header(netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
    const struct ipv6_routing_header *rh;
    int len, i;
    u_int nh, hdrlen;

    rh = (const struct ipv6_routing_header *)bp;
    len = 0;

    if (rh == NULL)
        return (-1);

    if (rh->ip6r_type == 0) {
        hdrlen = (ntohs(rh->ip6r_len) + 1) * 8;
        ND_PRINT("Routing header, type %u, length %u, segments left %u",
            rh->ip6r_type, ntohs(rh->ip6r_len), rh->ip6r_segleft);
        len += 16; /* size of routing header */
        for (i = 0; i < rh->ip6r_segleft; i++) {
            ND_PRINT("\n\t  Address %d: %s", i + 1,
                ip6addr_string(ndo, &rh->ip6r_data[i]));
            len += sizeof(struct in6_addr);
        }
    } else {
        ND_PRINT("Routing header, type %u (unknown), length %u",
            rh->ip6r_type, ntohs(rh->ip6r_len));
        len = -1;
    }

    return (len);
}

int
print_ipv6_routing_hdr(netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
    const struct ip6_rthdr *rh;
    int i, len, hdrlen;
    u_int nh;

    if ((unsigned)(bp - (const u_char *)NULL) + sizeof(*rh) > ndo->ndo_snaplen) {
        ND_PRINT((ndo, " [truncated]"));
        return (-1);
    }

    rh = (const struct ip6_rthdr *)bp;

    hdrlen = rh->ip6r_len * 4;
    len = hdrlen;

    ND_TCHECK(rh->ip6r_len);
    ND_PRINT((ndo, "RoutingHdr [Type %u, Length %u, Segments Left %u]",
             rh->ip6r_type, rh->ip6r_len * 4, rh->ip6r_segleft));

    switch (rh->ip6r_type) {
        case 0: /* IPv6 routing header type 0 */
        {
            const struct ip6_rthdr0 *rh0 = (const struct ip6_rthdr0 *)rh;
            int addrs;

            ND_TCHECK(rh0->ip6r0_type);
            addrs = rh0->ip6r0_type & 0x0f;

            if (addrs > 0) {
                ND_PRINT((ndo, ", %d Addresses: ", addrs));
                for (i = 0; i < addrs; i++) {
                    if (i > 0)
                        ND_PRINT((ndo, ", "));
                    ND_PRINT((ndo, "%s", ip6addr_string(ndo, (const u_char *)&rh0->ip6r0_addr[i])));
                }
            }
            break;
        }
        default:
            ND_PRINT((ndo, ", Unknown type, Data: "));
            ND_DEFAULTPRINT(rh, len);
            break;
    }

    ND_PRINT((ndo, "]"));
    return (len);
}

int print_ipv6_routing_header(netdissect_options *ndo, const u_char *bp, const u_char *bp2) {
    const struct ip6_rthdr *rh;
    int i, len;
    const u_char *ep;

    rh = (const struct ip6_rthdr *)bp;
    ep = ndo->ndo_snapend;

    if ((u_char *)&rh->ip6r_type > ep)
        return -1;

    ND_PRINT("%sRouting header: ", ndo->ndo_quoted ? "\"":"");
    ND_PRINT("type %d (", rh->ip6r_type);

    switch (rh->ip6r_type) {
        case 0:
            ND_PRINT("no routing information");
            break;
        case 2:
            ND_PRINT("type 2 (rfc3596)");
            break;
        case 4:
            ND_PRINT("type 4 (rfc8200)");
            break;
        default:
            ND_PRINT("unknown");
            break;
    }

    ND_PRINT("), segments left: %d", rh->ip6r_segleft);

    len = sizeof(*rh);
    if (rh->ip6r_type == 0)
        return len;

    if ((const u_char *)&rh->ip6r_nxt > ep)
        return -1;

    switch (rh->ip6r_type) {
        case 2: {
            const struct ip6_rthdr2 *rh2;
            int left;

            rh2 = (const struct ip6_rthdr2 *)rh;
            left = rh2->ip6r2_segleft;

            ND_PRINT(", address count: %d", left + 1);

            for (i = 0; i <= left; i++) {
                if (ep < (const u_char *)((const u_char *)&rh2->ip6r2_addr[i] + sizeof(rh2->ip6r2_addr[i])))
                    return -1;
                ND_PRINT(", address[%d]: ", i);
                ip6addr_to_str(ndo, &rh2->ip6r2_addr[i], 1, 0);
            }

            len += (left + 1) * sizeof(rh2->ip6r2_addr[0]);
            break;
        }

        default:
            ND_PRINT(", unknown routing header type");
            break;
    }

    return len;
}

int
print_ipv6_routing_header(netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
    const struct ip6_rthdr *rh;
    int len;
    u_int i, num_addrs;

    rh = (const struct ip6_rthdr *)bp;

    ND_PRINT((ndo, "Routing Header: Type %u, Length %u, Segments Left %u\n",
              rh->ip6r_type, rh->ip6r_len * 8, rh->ip6r_segleft));

    len = sizeof(struct ip6_rthdr);
    if (len > (int)(bp2 - bp)) {
        ND_PRINT((ndo, "[|truncated]"));
        return (-1);
    }

    switch (rh->ip6r_type) {
        case 0:
        case 2:
            num_addrs = rh->ip6r_segleft + 1;
            for (i = 0; i < num_addrs; i++) {
                if ((const u_char *)&rh->ip6r_addrs[i] > bp2) {
                    ND_PRINT((ndo, "[|truncated]"));
                    return (-1);
                }
                ND_PRINT((ndo, "\tAddress %u: %s\n", i+1, ip6addr_string(ndo, &rh->ip6r_addrs[i])));
            }
            len += num_addrs * sizeof(struct in6_addr);
            break;
        default:
            ND_PRINT((ndo, "Unknown routing type %u", rh->ip6r_type));
            break;
    }

    return len;
}
